AWS Network Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Boundary(aws_nlb, "AWS Network Load Balancer") {
    Component(tcp_ingress_router, "TCP Ingress Router", "AWS NLB L4 Routing", "Routes high-throughput payment authorization requests at 3,000 TPS to backend services.")
}

System_Ext(fraud_scoring_engine, "Fraud Scoring Engine", "Routes high-throughput scoring requests via TCP")

Rel(tcp_ingress_router, fraud_scoring_engine, "Routes high-throughput scoring requests via TCP", "TCP")

@enduml

Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis container

System_Ext(fraud_scoring_engine, "Fraud Scoring Engine", "External component interacting with Redis")

Container_Boundary(redis, "Redis") {
    Component(redis_primary_node, "Redis Primary Node", "Amazon ElastiCache (Redis OSS)", "Amazon ElastiCache instance handling real-time feature writes, fast reads, and executing Lua scripts for atomic rate-limiting.")
    Component(redis_replica_node, "Redis Replica Node", "Amazon ElastiCache (Redis OSS)", "Amazon ElastiCache instance providing automatic failover through asynchronous replication.")
    Component(in_memory_feature_cache_store, "In-Memory Feature Cache Store", "Redis Hashes and Sorted Sets", "Stores sliding-window velocity metrics using tokenized identifiers.")
}

Rel(fraud_scoring_engine, redis_primary_node, "Fetches features and executes Lua scripts for atomic rate-limiting and feature retrieval", "RESP protocol [TCP]")
Rel(redis_primary_node, redis_replica_node, "Synchronizes state via asynchronous replication", "RESP protocol via TCP")

@enduml

Amazon S3 with Object Lock and AWS KMS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(s3_kms_container, "Amazon S3 with Object Lock and AWS KMS") {
    Component(S3BucketComplianceAuditStore, "S3 Bucket (Compliance Audit Store)", "Amazon S3 with Object Lock", "Stores immutable audit logs with compliance mode ensuring 7-year tamper-evident retention.")
    Component(KeyManagementServiceAuditEncryptionKey, "Key Management Service (Audit Encryption Key)", "AWS KMS", "Provides envelope encryption keys to secure compliance audit payloads.")
    Component(S3LifecycleComponent, "S3 Lifecycle Component", "AWS S3 Lifecycle", "Transitions audit logs to Amazon S3 Glacier for cost-optimized long-term retention.")
    Component(BucketPolicyAccessController, "Bucket Policy & Access Controller", "AWS IAM & S3 Bucket Policies", "Enforces strict access controls and immutability rules on the compliance audit store.")
}

Rel(S3BucketComplianceAuditStore, KeyManagementServiceAuditEncryptionKey, "Encrypts/Decrypts payloads", "AWS internal API via AWS KMS VPC Endpoint")
Rel(S3LifecycleComponent, S3BucketComplianceAuditStore, "Transitions older audit logs to Glacier storage tier", "AWS internal API")
Rel(BucketPolicyAccessController, S3BucketComplianceAuditStore, "Applies security policies and prevents unauthorized modifications", "IAM Policy Engine")

@enduml
